// Normaliza el evento de WhatsApp Cloud API. No guarda estado: duplicados, origen y pausas viven en Postgres.
const j = $input.first().json;
const v = j.entry ? (((j.entry[0] || {}).changes || [])[0] || {}).value || {} : j;
const msg = (v.messages || [])[0];
if (!msg) return [];  // aviso de estado (enviado/entregado/leído): no hay nada que responder

const telefono = String(msg.from || '');
const contacto = (v.contacts || []).find(c => c.wa_id === telefono) || (v.contacts || [])[0] || {};

let texto = '';
if (msg.type === 'text') texto = (msg.text || {}).body || '';
else if (msg.type === 'button') texto = (msg.button || {}).text || '';
else if (msg.type === 'interactive') {
  const i = msg.interactive || {};
  texto = (i.button_reply || {}).title || (i.list_reply || {}).title || '';
} else if (['image', 'video', 'document'].includes(msg.type)) {
  const caption = (msg[msg.type] || {}).caption || '';
  texto = caption ? `[${msg.type} con texto] ${caption}` : '';
}

// Origen: anuncio Click-to-WhatsApp de Meta (referral) o código (ref: xxx) de nuestros enlaces
const ref = ((texto.match(/\(ref:\s*([a-z0-9-]+)\)/i) || [])[1] || '').toLowerCase();
const referral = msg.referral;
const origen = referral
  ? `Anuncio Meta: ${referral.headline || referral.source_type || 'anuncio'}` + (referral.source_id ? ` (id ${referral.source_id})` : '')
  : (ref ? `Enlace: ${ref}` : '');

const audio = msg.type === 'audio' || msg.type === 'voice' ? (msg.audio || msg.voice || {}) : null;

return [{
  json: {
    wamid: msg.id,
    telefono,
    nombre_perfil: (contacto.profile || {}).name || '',
    tipo: msg.type,
    texto: texto.replace(/\(ref:[^)]*\)/gi, '').trim(),
    origen,
    es_anuncio: Boolean(referral),
    es_audio: Boolean(audio && audio.id),
    audio_id: audio ? audio.id || '' : '',
    phone_number_id: (v.metadata || {}).phone_number_id || '',
  },
}];

// La API de transcripción reconoce el formato por la extensión del archivo: WhatsApp envía audio OGG/Opus sin nombre.
const item = $input.first();
const bin = item.binary && item.binary.data;
if (bin) {
  const ext = /mpeg|mp3/.test(bin.mimeType || '') ? 'mp3' : /mp4|m4a|aac/.test(bin.mimeType || '') ? 'm4a' : 'ogg';
  bin.fileName = `audio.${ext}`;
  bin.fileExtension = ext;
}
return [item];

// Reemplaza el audio por su transcripción. Si la transcripción falló, el texto queda vacío
// y el contacto recibe el mensaje de "solo puedo leer texto".
const prep = $('Preparar Mensaje').first().json;
const transcripcion = String(($input.first().json || {}).text || '').trim();
return [{ json: { ...prep, texto: transcripcion ? `[audio transcrito] ${transcripcion}` : '' } }];

// Arma el turno para el agente con todos los mensajes agrupados y decide la ruta.
const lote = $input.first().json;
const prep = $('Preparar Mensaje').first().json;
const texto = String(lote.texto_cliente || '').trim();

return [{
  json: {
    ruta: lote.pausado ? 'pausado' : (texto ? 'agente' : 'no_texto'),
    telefono: lote.telefono,
    nombre_perfil: lote.nombre_perfil,
    origen: lote.origen,
    tipos: lote.tipos,
    mensajes: Number(lote.mensajes),
    texto_cliente: texto,
    phone_number_id: prep.phone_number_id,
    mensaje_para_agente:
      '[Contexto del sistema]\n' +
      `Nombre de perfil de WhatsApp: ${lote.nombre_perfil || 'desconocido'}\n` +
      `Origen del contacto: ${lote.origen}\n` +
      (Number(lote.mensajes) > 1 ? `El cliente envió ${lote.mensajes} mensajes seguidos; respóndelos juntos en un solo mensaje.\n` : '') +
      '[Fin del contexto del sistema]\n\n' +
      `Mensaje del cliente:\n${texto}`,
  },
}];

